**Logic**

A class should have one reason to change. "Reason to change" means a stakeholder or concern, not a method count: a class doing report calculation, formatting and emailing answers to finance, design and infrastructure, so any of the three can force an edit, and a change for one risks breaking the others.

The practical test is to describe the class in one sentence. If you need "and", it probably has more than one responsibility.

**Program**

```csharp
using System;
using System.Collections.Generic;

public record Order(string Customer, decimal Amount);

// BAD: three responsibilities. Changing the tax rate, the wording of the
// receipt, or the delivery mechanism all force an edit to this one class.
public class OrderProcessorBad
{
    public void Process(Order order)
    {
        decimal tax = order.Amount * 0.2m;                       // business rule
        string receipt = $"Receipt for {order.Customer}: {order.Amount + tax:F2}";  // formatting
        Console.WriteLine($"[email] {receipt}");                 // delivery
    }
}

// GOOD: one reason to change each.
public class TaxCalculator
{
    public decimal Calculate(Order order) => order.Amount * 0.2m;
}

public class ReceiptFormatter
{
    public string Format(Order order, decimal tax) =>
        $"Receipt for {order.Customer}: {order.Amount + tax:F2}";
}

public interface INotifier { void Send(string message); }

public class EmailNotifier : INotifier
{
    public void Send(string message) => Console.WriteLine($"[email] {message}");
}

public class SmsNotifier : INotifier
{
    public void Send(string message) => Console.WriteLine($"[sms] {message}");
}

// The processor now coordinates; it owns none of the three concerns.
public class OrderProcessor
{
    private readonly TaxCalculator _tax;
    private readonly ReceiptFormatter _formatter;
    private readonly INotifier _notifier;

    public OrderProcessor(TaxCalculator tax, ReceiptFormatter formatter, INotifier notifier)
    { _tax = tax; _formatter = formatter; _notifier = notifier; }

    public void Process(Order order)
    {
        decimal tax = _tax.Calculate(order);
        _notifier.Send(_formatter.Format(order, tax));
    }
}

public class Solution
{
    public static void Main()
    {
        var order = new Order("Priya", 100m);

        new OrderProcessorBad().Process(order);

        var processor = new OrderProcessor(new TaxCalculator(), new ReceiptFormatter(), new EmailNotifier());
        processor.Process(order);

        // Switching the delivery mechanism now touches no existing class.
        new OrderProcessor(new TaxCalculator(), new ReceiptFormatter(), new SmsNotifier()).Process(order);

        // And the tax rule is independently testable, which it was not before.
        Console.WriteLine(new TaxCalculator().Calculate(new Order("Test", 250m)));
    }
}
```

**Output**

```
[email] Receipt for Priya: 120.00
[email] Receipt for Priya: 120.00
[sms] Receipt for Priya: 120.00
50.0
```

Note the deliberate use of `F2` rather than `C`. Currency formatting depends on the thread culture, so `C` would print a different symbol on a developer laptop than on a server in another region - which is itself an argument that formatting is a separate concern with its own rules.

**Logic**

Software should be open for extension but closed for modification: adding new behaviour should mean adding code, not editing code that already works and is already tested.

The smell is a switch or if-else chain over a type code. Every new case forces an edit to the same method, so each addition risks breaking the existing cases and re-tests them all. Replacing the chain with polymorphism moves the decision to the type system: a new behaviour is a new class, and nothing existing changes.

**Program**

```csharp
using System;
using System.Collections.Generic;

// BAD: every new shape means editing this method, re-testing every branch.
public class AreaCalculatorBad
{
    public double Area(object shape) => shape switch
    {
        (double w, double h) => w * h,
        double r => Math.PI * r * r,
        _ => throw new NotSupportedException("unknown shape"),
    };
}

// GOOD: the abstraction is closed, the set of implementations is open.
public interface IShape
{
    double Area();
}

public class Rectangle : IShape
{
    private readonly double _w, _h;
    public Rectangle(double w, double h) { _w = w; _h = h; }
    public double Area() => _w * _h;
}

public class Circle : IShape
{
    private readonly double _r;
    public Circle(double r) { _r = r; }
    public double Area() => Math.PI * _r * _r;
}

// Added later. Note that no existing class or method was touched.
public class Triangle : IShape
{
    private readonly double _b, _h;
    public Triangle(double b, double h) { _b = b; _h = h; }
    public double Area() => 0.5 * _b * _h;
}

public class Solution
{
    public static void Main()
    {
        var shapes = new List<IShape>
        {
            new Rectangle(3, 4),
            new Circle(1),
            new Triangle(6, 2),      // the new case needed no edit anywhere
        };

        double total = 0;
        foreach (var s in shapes)
        {
            Console.WriteLine(s.Area().ToString("F2"));
            total += s.Area();
        }

        Console.WriteLine(total.ToString("F2"));

        // The old version throws the moment it meets something it was not edited for.
        try { new AreaCalculatorBad().Area("triangle"); }
        catch (NotSupportedException e) { Console.WriteLine(e.Message); }
    }
}
```

**Output**

```
12.00
3.14
6.00
21.14
unknown shape
```

**Logic**

Anywhere a base type is expected, any derived type must work without the caller noticing. Inheritance is a promise about behaviour, not just about shared fields: a subtype may not strengthen what it demands of callers or weaken what it guarantees in return.

The classic violation is Square inheriting Rectangle. A rectangle promises that setting width leaves height alone; a square cannot keep that promise. The code compiles and the "is-a" reading sounds right, yet any caller written against Rectangle breaks.

**Program**

```csharp
using System;

// BAD: Square is-a Rectangle in geometry, but not in behaviour.
public class RectangleBad
{
    public virtual int Width { get; set; }
    public virtual int Height { get; set; }
    public int Area => Width * Height;
}

public class SquareBad : RectangleBad
{
    public override int Width
    {
        get => base.Width;
        set { base.Width = value; base.Height = value; }   // silently changes Height
    }

    public override int Height
    {
        get => base.Height;
        set { base.Width = value; base.Height = value; }
    }
}

// GOOD: no inheritance claim that cannot be kept. Both are shapes; neither
// pretends to be substitutable for the other.
public interface IShape { int Area { get; } }

public sealed class Rectangle : IShape
{
    public Rectangle(int width, int height) { Width = width; Height = height; }
    public int Width { get; }
    public int Height { get; }
    public int Area => Width * Height;
}

public sealed class Square : IShape
{
    public Square(int side) { Side = side; }
    public int Side { get; }
    public int Area => Side * Side;
}

public class Solution
{
    // A caller written against RectangleBad. Entirely reasonable expectation.
    private static void ResizeAndReport(RectangleBad r)
    {
        r.Width = 4;
        r.Height = 5;
        Console.WriteLine($"expected 20, got {r.Area}");
    }

    public static void Main()
    {
        ResizeAndReport(new RectangleBad());   // fine
        ResizeAndReport(new SquareBad());      // same code, wrong answer

        Console.WriteLine(new Rectangle(4, 5).Area);
        Console.WriteLine(new Square(4).Area);

        // Immutability removes the problem at the root: with no setters there is
        // no invariant for a subtype to break.
        IShape[] shapes = { new Rectangle(2, 3), new Square(3) };
        foreach (var s in shapes) Console.WriteLine(s.Area);
    }
}
```

**Output**

```
expected 20, got 20
expected 20, got 25
20
16
6
9
```

The second line is the violation made visible: identical caller code, silently wrong result.

**Logic**

No client should be forced to depend on methods it does not use. A large interface drags every implementer into supporting behaviour it may not have, which produces either meaningless implementations or exceptions thrown from methods that should not have been there.

Splitting a fat interface into focused ones lets each implementer take only what it can honour, and lets each caller depend only on what it actually calls. The knock-on benefit is testing: a mock of a two-method interface is trivial, a mock of a twelve-method interface is a chore.

**Program**

```csharp
using System;

// BAD: a printer that cannot fax is forced to implement Fax anyway.
public interface IMultiFunctionDevice
{
    void Print(string document);
    void Scan(string document);
    void Fax(string document);
}

public class BasicPrinterBad : IMultiFunctionDevice
{
    public void Print(string d) => Console.WriteLine($"printing {d}");
    public void Scan(string d) => throw new NotSupportedException("no scanner");
    public void Fax(string d) => throw new NotSupportedException("no fax");
}

// GOOD: small interfaces, composed only where the capability truly exists.
public interface IPrinter { void Print(string document); }
public interface IScanner { void Scan(string document); }
public interface IFax { void Fax(string document); }

public class BasicPrinter : IPrinter
{
    public void Print(string d) => Console.WriteLine($"printing {d}");
}

public class OfficeMachine : IPrinter, IScanner, IFax
{
    public void Print(string d) => Console.WriteLine($"printing {d}");
    public void Scan(string d) => Console.WriteLine($"scanning {d}");
    public void Fax(string d) => Console.WriteLine($"faxing {d}");
}

public class Solution
{
    // The caller states exactly what it needs, so a basic printer is acceptable.
    private static void PrintReport(IPrinter printer) => printer.Print("report.pdf");

    public static void Main()
    {
        PrintReport(new BasicPrinter());
        PrintReport(new OfficeMachine());

        new OfficeMachine().Fax("contract.pdf");

        // The fat interface only fails at run time, and only for some implementers.
        try { new BasicPrinterBad().Fax("contract.pdf"); }
        catch (NotSupportedException e) { Console.WriteLine("failed: " + e.Message); }
    }
}
```

**Output**

```
printing report.pdf
printing report.pdf
faxing contract.pdf
failed: no fax
```

**Logic**

High-level policy should not depend on low-level detail; both should depend on an abstraction. And the abstraction should be owned by the high-level side, expressed in its language, rather than being a mirror of whatever the database or mail server happens to offer.

Concretely: a service that news up a `SqlRepository` is welded to SQL Server. Taking an `IUserRepository` in its constructor means the same service works against SQL, an in-memory fake, or a cache, and can be tested without a database. The "inversion" is that the dependency arrow now points from the detail to the policy rather than the other way round.

**Program**

```csharp
using System;
using System.Collections.Generic;

public record User(int Id, string Name);

// BAD: the service constructs its own dependency, so it cannot be tested,
// swapped, or reused without a real database.
public class UserServiceBad
{
    private readonly SqlUserRepository _repo = new();
    public string Describe(int id) => _repo.Find(id)?.Name ?? "not found";
}

// The abstraction is defined by the consumer's needs, not the database's shape.
public interface IUserRepository
{
    User Find(int id);
}

public class SqlUserRepository : IUserRepository
{
    public User Find(int id)
    {
        Console.WriteLine($"[sql] select * from users where id = {id}");
        return id == 1 ? new User(1, "Priya") : null;
    }
}

// A test double: no database, no network, no configuration.
public class InMemoryUserRepository : IUserRepository
{
    private readonly Dictionary<int, User> _users;
    public InMemoryUserRepository(params User[] users)
    {
        _users = new Dictionary<int, User>();
        foreach (var u in users) _users[u.Id] = u;
    }
    public User Find(int id) => _users.TryGetValue(id, out var u) ? u : null;
}

// GOOD: depends on the abstraction and is handed the implementation.
public class UserService
{
    private readonly IUserRepository _repo;
    public UserService(IUserRepository repo) => _repo = repo;

    public string Describe(int id) => _repo.Find(id)?.Name ?? "not found";
}

public class Solution
{
    public static void Main()
    {
        var production = new UserService(new SqlUserRepository());
        Console.WriteLine(production.Describe(1));
        Console.WriteLine(production.Describe(2));

        // The same policy, tested in microseconds with no infrastructure at all.
        var underTest = new UserService(new InMemoryUserRepository(new User(7, "Test User")));
        Console.WriteLine(underTest.Describe(7));
        Console.WriteLine(underTest.Describe(99));

        Console.WriteLine(new UserServiceBad().Describe(1));   // always hits SQL
    }
}
```

**Output**

```
[sql] select * from users where id = 1
Priya
[sql] select * from users where id = 2
not found
Test User
not found
[sql] select * from users where id = 1
Priya
```
